BEGIN;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS foundation_lesson_ids TEXT[] NOT NULL DEFAULT '{}';
INSERT INTO public.lessons (id,course_id,skill_id,title,summary,estimated_minutes,steps,reinforcement_exercise,is_published,is_archived) VALUES ('lesson_math_foundation_02','course_math_01','skill_math_algebra','Teng guruhlar va ko‘paytirish','Ko‘paytirish teng sonlarni takror qo‘shishdir. 3 × 2 uchta 2 sonini qo‘shishni bildiradi.',5,'[{"id": "lesson_math_foundation_02_read", "stepNumber": 1, "type": "concept", "title": "Asosiy tushuncha", "content": "Ko‘paytirish teng sonlarni takror qo‘shishdir. 3 × 2 uchta 2 sonini qo‘shishni bildiradi."}, {"id": "lesson_math_foundation_02_example", "stepNumber": 2, "type": "visual_example", "title": "Birga misol ko‘ramiz", "content": "Har birida 2 ta qalam bo‘lgan 3 quti bor. 2 + 2 + 2 = 6, shuning uchun 3 × 2 = 6."}, {"id": "lesson_math_foundation_02_try", "stepNumber": 3, "type": "interactive_question", "title": "O‘rganganingizni sinab ko‘ring", "content": "Misolga tayangan holda javobni tanlang.", "interactiveQuestion": {"id": "q_lesson_math_foundation_02", "courseId": "course_math_01", "skillId": "skill_math_algebra", "text": "Har birida 3 ta olma bo‘lgan 2 savatda jami nechta olma bor?", "options": ["5", "6", "3"], "correctIndex": 1, "difficulty": "easy", "explanation": "3 + 3 = 6. Ikki guruhda uchtadan olma bor."}}]'::jsonb,'{"id": "q_lesson_math_foundation_02_practice", "courseId": "course_math_01", "skillId": "skill_math_algebra", "text": "Har birida 3 ta olma bo‘lgan 2 savatda jami nechta olma bor?", "options": ["5", "6", "3"], "correctIndex": 1, "difficulty": "easy", "explanation": "3 + 3 = 6. Ikki guruhda uchtadan olma bor."}'::jsonb,true,false) ON CONFLICT (id) DO NOTHING;
UPDATE public.courses SET foundation_lesson_ids=ARRAY['lesson_math_starter','lesson_math_foundation_02'] WHERE id='course_math_01' AND cardinality(foundation_lesson_ids)=0;
INSERT INTO public.lessons (id,course_id,skill_id,title,summary,estimated_minutes,steps,reinforcement_exercise,is_published,is_archived) VALUES ('lesson_eng_foundation_02','course_eng_01','skill_eng_grammar','Men, siz va oddiy gaplar','I — men, you — siz, he — u (erkak), she — u (ayol). I bilan am, you bilan are, he va she bilan is ishlatiladi. Student — o‘quvchi.',5,'[{"id": "lesson_eng_foundation_02_read", "stepNumber": 1, "type": "concept", "title": "Asosiy tushuncha", "content": "I — men, you — siz, he — u (erkak), she — u (ayol). I bilan am, you bilan are, he va she bilan is ishlatiladi. Student — o‘quvchi."}, {"id": "lesson_eng_foundation_02_example", "stepNumber": 2, "type": "visual_example", "title": "Birga misol ko‘ramiz", "content": "I am a student. — Men o‘quvchiman. You are a student. — Siz o‘quvchisiz. She is a student. — U o‘quvchi. A so‘zi bu yerda bitta o‘quvchi haqida gapirilayotganini bildiradi."}, {"id": "lesson_eng_foundation_02_try", "stepNumber": 3, "type": "interactive_question", "title": "O‘rganganingizni sinab ko‘ring", "content": "Misolga tayangan holda javobni tanlang.", "interactiveQuestion": {"id": "q_lesson_eng_foundation_02", "courseId": "course_eng_01", "skillId": "skill_eng_grammar", "text": "«Men o‘quvchiman» gapini to‘ldiring. I ___ a student.", "options": ["is", "am", "are"], "correctIndex": 1, "difficulty": "easy", "explanation": "I bilan am ishlatiladi. I am a student — Men o‘quvchiman."}}]'::jsonb,'{"id": "q_lesson_eng_foundation_02_practice", "courseId": "course_eng_01", "skillId": "skill_eng_grammar", "text": "«Men o‘quvchiman» gapini to‘ldiring. I ___ a student.", "options": ["is", "am", "are"], "correctIndex": 1, "difficulty": "easy", "explanation": "I bilan am ishlatiladi. I am a student — Men o‘quvchiman."}'::jsonb,true,false) ON CONFLICT (id) DO NOTHING;
UPDATE public.courses SET foundation_lesson_ids=ARRAY['lesson_eng_starter','lesson_eng_foundation_02'] WHERE id='course_eng_01' AND cardinality(foundation_lesson_ids)=0;
INSERT INTO public.lessons (id,course_id,skill_id,title,summary,estimated_minutes,steps,reinforcement_exercise,is_published,is_archived) VALUES ('lesson_it_foundation_02','course_it','skill_it_python','Son va matnni farqlash','Python’da qo‘shtirnoq ichidagi yozuv matn hisoblanadi. Qo‘shtirnoqsiz sonlar bilan hisoblash mumkin.',5,'[{"id": "lesson_it_foundation_02_read", "stepNumber": 1, "type": "concept", "title": "Asosiy tushuncha", "content": "Python’da qo‘shtirnoq ichidagi yozuv matn hisoblanadi. Qo‘shtirnoqsiz sonlar bilan hisoblash mumkin."}, {"id": "lesson_it_foundation_02_example", "stepNumber": 2, "type": "visual_example", "title": "Birga misol ko‘ramiz", "content": "print(2 + 3) ekranga 5 chiqaradi. print(\"2 + 3\") esa 2 + 3 yozuvini chiqaradi. Qo‘shtirnoq yozuvni o‘z holicha saqlaydi."}, {"id": "lesson_it_foundation_02_try", "stepNumber": 3, "type": "interactive_question", "title": "O‘rganganingizni sinab ko‘ring", "content": "Misolga tayangan holda javobni tanlang.", "interactiveQuestion": {"id": "q_lesson_it_foundation_02", "courseId": "course_it", "skillId": "skill_it_python", "text": "print(3 + 4) qanday natija chiqaradi?", "options": ["3 + 4", "34", "7"], "correctIndex": 2, "difficulty": "easy", "explanation": "Qo‘shtirnoqsiz sonlar qo‘shiladi. 3 + 4 = 7."}}]'::jsonb,'{"id": "q_lesson_it_foundation_02_practice", "courseId": "course_it", "skillId": "skill_it_python", "text": "print(3 + 4) qanday natija chiqaradi?", "options": ["3 + 4", "34", "7"], "correctIndex": 2, "difficulty": "easy", "explanation": "Qo‘shtirnoqsiz sonlar qo‘shiladi. 3 + 4 = 7."}'::jsonb,true,false) ON CONFLICT (id) DO NOTHING;
UPDATE public.courses SET foundation_lesson_ids=ARRAY['lesson_it_starter','lesson_it_foundation_02'] WHERE id='course_it' AND cardinality(foundation_lesson_ids)=0;
INSERT INTO public.lessons (id,course_id,skill_id,title,summary,estimated_minutes,steps,reinforcement_exercise,is_published,is_archived) VALUES ('lesson_logic_foundation_02','course_logic','skill_logic_puzzles','Mulohazani inkor qilish','Inkor bir mulohazaning rostlik qiymatini teskarisiga o‘zgartiradi. Rost mulohazaning inkori yolg‘on bo‘ladi.',5,'[{"id": "lesson_logic_foundation_02_read", "stepNumber": 1, "type": "concept", "title": "Asosiy tushuncha", "content": "Inkor bir mulohazaning rostlik qiymatini teskarisiga o‘zgartiradi. Rost mulohazaning inkori yolg‘on bo‘ladi."}, {"id": "lesson_logic_foundation_02_example", "stepNumber": 2, "type": "visual_example", "title": "Birga misol ko‘ramiz", "content": "«5 soni 3 dan katta» rost. Uning inkori «5 soni 3 dan katta emas» yolg‘on. Inkor odatda emas so‘zi bilan ifodalanadi."}, {"id": "lesson_logic_foundation_02_try", "stepNumber": 3, "type": "interactive_question", "title": "O‘rganganingizni sinab ko‘ring", "content": "Misolga tayangan holda javobni tanlang.", "interactiveQuestion": {"id": "q_lesson_logic_foundation_02", "courseId": "course_logic", "skillId": "skill_logic_puzzles", "text": "«2 + 2 = 4» rost. Uning inkori qanday baholanadi?", "options": ["Rost", "Yolg‘on", "Savol"], "correctIndex": 1, "difficulty": "easy", "explanation": "Rost mulohazaning inkori yolg‘on bo‘ladi."}}]'::jsonb,'{"id": "q_lesson_logic_foundation_02_practice", "courseId": "course_logic", "skillId": "skill_logic_puzzles", "text": "«2 + 2 = 4» rost. Uning inkori qanday baholanadi?", "options": ["Rost", "Yolg‘on", "Savol"], "correctIndex": 1, "difficulty": "easy", "explanation": "Rost mulohazaning inkori yolg‘on bo‘ladi."}'::jsonb,true,false) ON CONFLICT (id) DO NOTHING;
UPDATE public.courses SET foundation_lesson_ids=ARRAY['lesson_logic_starter','lesson_logic_foundation_02'] WHERE id='course_logic' AND cardinality(foundation_lesson_ids)=0;
NOTIFY pgrst, 'reload schema';
COMMIT;
